try {
    var KETSU_ASYNC = true;

    function Listing ( request, extra, javascriptConfig, output ) {
        this.request = request;
        this.extra = extra;
        this.separator = '';
        this.javascriptConfig = javascriptConfig;
        this.output = output;
    }
    function ModuleRequest ( url, method, headers, httpBody ) {
        this.url = url; this.method = method; this.headers = headers; this.httpBody = httpBody;
    }
    function Extra ( commands, extraInfo ) { this.commands = commands; this.extraInfo = extraInfo; }
    function Commands ( commandName, params ) { this.commandName = commandName; this.params = params; }
    function JavascriptConfig ( removeJavascript, loadInWebView, javaScript ) {
        this.removeJavascript = removeJavascript; this.loadInWebView = loadInWebView; this.javaScript = javaScript;
    }
    function KeyValue ( key, value ) { this.key = key; this.value = value; }
    function Insets ( top, bottom, left, right ) {
        this.top = top; this.bottom = bottom; this.left = left; this.right = right;
    }
    function Size ( width, height ) { this.width = width; this.height = height; }
    function Ratio ( inRelation, number1, number2 ) {
        this.inRelation = inRelation; this.number1 = number1; this.number2 = number2;
    }
    function Section ( sectionName, separator ) { this.sectionName = sectionName; this.separator = separator; }
    function Layout ( insets, visibleCellsWidthS, visibleCellsWidthM, visibleCellsWidthL,
        visibleCellsHeight, heightForVisibleCells, cellSize, ratio, constant,
        horizontalSpacing, verticalSpacing ) {
        this.insets = insets;
        this.visibleCellsWidthS = visibleCellsWidthS;
        this.visibleCellsWidthM = visibleCellsWidthM;
        this.visibleCellsWidthL = visibleCellsWidthL;
        this.visibleCellsHeight = visibleCellsHeight;
        this.heightForVisibleCells = heightForVisibleCells;
        this.cellSize = cellSize;
        this.ratio = ratio;
        this.constant = constant;
        this.horizontalSpacing = horizontalSpacing;
        this.verticalSpacing = verticalSpacing;
    }
    function Output ( cellDesing, orientation, defaultLayout, paging, section, layout, data ) {
        this.cellDesing = cellDesing; this.orientation = orientation;
        this.defaultLayout = defaultLayout; this.paging = paging;
        this.section = section; this.layout = layout; this.data = data;
    }
    function Data ( image, title, description, field1, field2, field3, field4,
        isChapter, link, openInWebView ) {
        this.image = image; this.title = title; this.description = description;
        this.field1 = field1; this.field2 = field2; this.field3 = field3; this.field4 = field4;
        this.isChapter = isChapter; this.link = link; this.openInWebView = openInWebView;
    }

    var ORIGIN = 'https://anikototv.to';
    var EMPTY = [ new KeyValue( '', '' ) ];
    function clean ( value ) { return String( value || '' ).replace( /\s+/g, ' ' ).trim(); }
    function absolute ( value ) {
        try { return new URL( String( value || '' ), ORIGIN + '/' ).href; } catch ( ignored ) { return ''; }
    }
    function request ( url, referer ) {
        return new ModuleRequest( String( url || '' ), 'get', [
            new KeyValue( 'Referer', referer || ORIGIN + '/' ),
            new KeyValue( 'Accept-Language', 'en-US,en;q=0.9' )
        ], null );
    }
    function titleUrl ( value ) {
        return absolute( value ).replace( /#.*$/, '' );
    }
    function layout ( ) {
        return new Layout(
            new Insets( 10, 10, 10, 10 ), 2, 3, 4, 1, 360,
            new Size( 240, 360 ), new Ratio( 'width', 2, 3 ),
            new Size( 0, 0 ), 10, 12
        );
    }

    var rows = [ ];
    var seen = { };
    Array.from( document.querySelectorAll( '.item' ) ).forEach( function ( item ) {
        var anchor = item.querySelector( '.info a.name[href*="/watch/"]' ) ||
            item.querySelector( 'a[href*="/watch/"]' );
        var image = item.querySelector( 'img' );
        var link = anchor ? titleUrl( anchor.getAttribute( 'href' ) ) : '';
        var title = clean( anchor && anchor.textContent ) || clean( image && image.getAttribute( 'alt' ) );
        if ( !link || !title || seen[ link ] ) return;
        seen[ link ] = true;

        var type = clean( item.querySelector( '.poster .meta .right' ) &&
            item.querySelector( '.poster .meta .right' ).textContent );
        var sub = clean( item.querySelector( '.ep-status.sub span' ) &&
            item.querySelector( '.ep-status.sub span' ).textContent );
        var dub = clean( item.querySelector( '.ep-status.dub span' ) &&
            item.querySelector( '.ep-status.dub span' ).textContent );
        var total = clean( item.querySelector( '.ep-status.total span' ) &&
            item.querySelector( '.ep-status.total span' ).textContent );
        var details = [ ];
        if ( sub ) details.push( 'SUB ' + sub );
        if ( dub ) details.push( 'DUB ' + dub );
        if ( total ) details.push( total + ' total' );

        rows.push( new Data(
            request( image ? absolute( image.getAttribute( 'data-src' ) || image.getAttribute( 'src' ) ) : '', location.href ),
            title,
            details.join( ' • ' ),
            type,
            sub ? 'SUB ' + sub : '',
            dub ? 'DUB ' + dub : '',
            total ? total + ' episodes' : '',
            false,
            request( link, location.href ),
            false
        ) );
    } );

    if ( !rows.length ) {
        rows.push( new Data(
            request( '', location.href ),
            'No titles found',
            'The page did not expose any public title cards. Try the site fallback.',
            '', '', '', '', false, request( location.href || ORIGIN + '/', ORIGIN + '/' ), true
        ) );
    }

    var next = document.querySelector( 'a[rel="next"], .pagination .next a, .pagination a[aria-label*="Next"]' );
    var nextUrl = next ? absolute( next.getAttribute( 'href' ) ) : '';
    var output = [ new Output(
        'wide8', 'vertical', '', '', new Section(
            location.pathname.indexOf( '/filter' ) === 0 ? 'Search Results' : 'Latest Releases', true
        ), layout( ), rows
    ) ];
    var savedData = document.getElementById( 'ketsu-final-data' );
    var listing = new Listing(
        request( nextUrl, location.href ),
        new Extra( [ new Commands( '', EMPTY ) ], EMPTY ),
        new JavascriptConfig( true, false, '' ),
        output
    );
    savedData.innerHTML = JSON.stringify( listing );
    window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage( '' );
} catch ( error ) {
    console.error( error && error.message ? error.message : error );
    try { window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage( '' ); } catch ( ignored ) {}
}

