            seen[ linkId ] = true;
            choices.push( new NeedsResolver(
                'AnikotoTV Embed - ' + type + ' - ' + serverName( item.textContent ),
                pageRequest(
                    ORIGIN + '/ajax/server?get=' + encodeURIComponent( linkId ),
                    episodeUrl, true
                )
            ) );
        } );
    } );
    choices.push( new NeedsResolver(
        'AnikotoTV Web Player - Normal episode page',
        pageRequest( episodeUrl, ORIGIN + '/', false )
    ) );
    var result = new Chapters(
        pageRequest( '', episodeUrl, false ),
        new Extra( [ new Commands( '', EMPTY ) ], [
            new KeyValue( 'publicServerCount', String( Math.max( 0, choices.length - 1 ) ) ),
            new KeyValue( 'fallback', episodeUrl )
        ] ),
        new JavascriptConfig( false, false, '' ),
        new Output(
            new Videos( choices, [ ] ),
            [ ],
            { text: choices.length > 1
                ? 'Choose a public SUB, HSUB, or DUB server. The normal episode page is the final fallback.'
                : 'No public server list was returned. Use the normal episode page fallback.' }
        )
    );
    savedData.innerHTML = JSON.stringify( result );
